function wordVisual(w:any,category=''){
 if(typeof w?.image==='string'&&w.image.trim()) return w.image
 const en=String(w?.en||'').trim(), ru=String(w?.ru||'').trim(), hay=`${en} ${ru} ${category}`
 if(/^(plane|airplane|aeroplane|aircraft)$/i.test(en)) return '/word-plane.png'
 const kind=visualRules.find(([re])=>re.test(hay))?.[1]||'book'; const shape=visualShapes[kind]||visualShapes.book
 // Every lexical entry receives its own deterministic composition. It stays local,
 // transparent and stable across sessions; no emoji/CDN/image request is used.
 let h=2166136261; for(const ch of `${en}|${ru}|${category}`){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)} h>>>=0
 const a=25+(h%300), b=20+((h>>>8)%310), c=18+((h>>>16)%170), rot=(h%23)-11
 const r1=18+(h%24), r2=12+((h>>>5)%22), x1=65+(h%90), x2=275+((h>>>9)%80), y1=45+((h>>>13)%70), y2=145+((h>>>17)%55)
 const label=en.slice(0,34).replace(/[&<>]/g,'')
 const safeKind=kind.replace(/[^a-z]/g,'')
 return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 260" role="img" aria-label="${label}"><defs><linearGradient id="ink" x1="0" y1="0" x2="1" y2="1"><stop stop-color="hsl(${a} 72% 52%)"/><stop offset="1" stop-color="hsl(${b} 74% 70%)"/></linearGradient><radialGradient id="glow"><stop stop-color="hsl(${c} 85% 78%)" stop-opacity=".48"/><stop offset="1" stop-color="white" stop-opacity="0"/></radialGradient><filter id="s" x="-30%" y="-30%" width="160%" height="160%"><feDropShadow dx="0" dy="9" stdDeviation="9" flood-color="hsl(${a} 45% 42%)" flood-opacity=".18"/></filter></defs><g opacity=".95"><circle cx="${x1}" cy="${y1}" r="${r1}" fill="url(#glow)"/><circle cx="${x2}" cy="${y2}" r="${r2}" fill="url(#glow)"/></g><g data-visual="${safeKind}" transform="rotate(${rot} 210 135)" stroke-linecap="round" stroke-linejoin="round" filter="url(#s)"><g fill="url(#ink)" fill-opacity=".16" stroke="hsl(${a} 78% 38%)" stroke-opacity=".18" stroke-width="16">${shape}</g><g fill="none" stroke="url(#ink)" stroke-width="8">${shape}</g><g transform="translate(-2 -3)" fill="none" stroke="white" stroke-opacity=".72" stroke-width="2.2">${shape}</g></g><ellipse cx="210" cy="218" rx="108" ry="11" fill="hsl(${a} 55% 45%)" opacity=".08"/><path d="M88 220 C145 ${205-(h%18)} 275 ${235-(h%22)} 332 218" fill="none" stroke="url(#ink)" stroke-width="3" opacity=".18"/><text x="210" y="246" text-anchor="middle" font-family="Arial,sans-serif" font-size="17" font-weight="700" fill="hsl(${a} 40% 38%)">${label}</text></svg>`)}`
}

// Session + persistent cache. Curriculum is downloaded once, then reused across Activity restarts.
const publicContentCache=new Map<Section,Content[]>()
let leaderboardSessionCache:any[]|null=null
let leaderboardSessionPromise:Promise<any[]>|null=null
let adminBootstrapCache:{missions:Mission[];items:Content[];settings:MewaySettings}|null=null
let adminBootstrapPromise:Promise<any>|null=null
