function SafeAvatar({src,fallback,name}:{src:string;fallback:string;name:string}){const [failed,setFailed]=useState(false);const shown=!failed?(src||fallback):fallback;return shown?<img src={shown} alt="" onError={()=>setFailed(true)}/>:<>{name[0]?.toUpperCase()}</>}
function Topbar({name,xp,avatar,fallbackAvatar}:{name:string;xp:number;avatar:string;fallbackAvatar:string}){return <header className="topbar"><div className="crumb"><span>MEWAY SPACE</span><b>Учись. Играй. Расти.</b></div><div className="topActions"><span className="streak">🔥 На связи</span><span className="xpPill">⚡ {xp} XP</span><div className="avatar"><SafeAvatar src={avatar} fallback={fallbackAvatar} name={name}/></div></div></header>}
