function Missions({missions,completed,openMission}:{missions:Mission[];completed:number[];openMission:(m:Mission)=>void}){const [level,setLevel]=useState('Все'),[topicSearch,setTopicSearch]=useState(''),[selectedTopics,setSelectedTopics]=useState<string[]>([]);useEffect(()=>{setTopicSearch('');setSelectedTopics([])},[level]);const levelMissions=level==='Все'?missions:missions.filter(m=>m.level===level);const categories=levelMissions.map(m=>m.category).filter(Boolean);const tq=topicSearch.trim().toLocaleLowerCase();const shown=levelMissions.filter(m=>(!selectedTopics.length||selectedTopics.includes(m.category))&&(!tq||String(m.category||'').toLocaleLowerCase().includes(tq)));return <><PageHero icon="🎯" kicker="УЧЕБНЫЙ МАРШРУТ" title="Выбери следующую миссию" text="Проходи задания в своём темпе и получай XP за завершённые миссии."/><div className="filterStack"><div className="filters compact">{['Все','A1','A2','B1','B2','C1','C2'].map(x=><button className={level===x?'active':''} onClick={()=>setLevel(x)} key={x}>{x}</button>)}</div>{categories.length>0&&<TopicPicker categories={categories} selected={selectedTopics} onChange={setSelectedTopics} search={topicSearch} onSearchChange={setTopicSearch}/>}</div>{shown.length?<section className="cards">{shown.map(m=><div className="cardWrap" key={m.id}>{completed.includes(m.id)&&<span className="done">✓ Выполнено</span>}<MissionCard m={m} completed={completed.includes(m.id)} onClick={()=>openMission(m)}/></div>)}</section>:<Empty title="Здесь пока пусто" text="Попробуй другой уровень, тему или очисти фильтр тем."/>}</>}
